"""Training opponent `balanced` (generated by opponents/build.py; do not edit).

All-round: relay cyclers that defend when the flag is taken nearby plus a flex player that intercepts carriers or joins the relay/escort; shared obstacle memory, trail following, full speed on remembered ground.
"""

STYLE = {'aggr': 2,
 'cycle_defend': True,
 'guard_v': 9.0,
 'jump': 1.0,
 'lanes': (0.0, 0.0, 0.0),
 'roles': ('cycle', 'cycle', 'flex'),
 'share': True,
 'sonar': True,
 'spawn_jump': True,
 'tag': 'BA',
 'trust_trail': True,
 'vfast': 17.64,
 'vsafe': 10.5}

# ---------------------------------------------------------------------------
# Shared core (generated from opponents/_core.py by opponents/build.py).
# Standard library only; reads documented observation keys only.
# ---------------------------------------------------------------------------
import math
import random

_PI = math.pi
_TAU = 2.0 * math.pi
_DT = 0.05
_VTOP = 17.64          # 18 cap after one tick of friction
_N = 200               # 1-unit memory grid over the 200x200 arena
_HOME_R2 = 16.0 ** 2   # no obstacle or ramp edge within ~17.5 of either home

S = dict(STYLE)
SEED = None  # chaos: set (e.g. to the match seed) for reproducible draws; None = fresh entropy


class _Mem(object):
    pass


M = _Mem()
M.ready = False
M.match_no = -1
M.goal = None  # (absolute heading, target speed) of the last _drive call; read by training labellers


def _clamp(v, lo=-1.0, hi=1.0):
    return lo if v < lo else hi if v > hi else v


def _norm(a):
    return (a + _PI) % _TAU - _PI


def _reset(obs):
    me = obs["self"]
    M.ready = True
    M.match_no += 1
    M.last_tick = obs["tick"]
    M.safe = bytearray(_N * _N)
    M.circles = []
    M.home = None
    M.ehome = None
    M.prev = None
    M.rev = False
    M.pp = 1
    M.seg0 = None
    M.segdir = None
    M.seglast = None
    M.share = []
    M.share_i = 0
    M.seen = set()
    M.deaths = set()
    M.trail = []
    M.enemy_last = {}
    M.side = {}
    M.stuck = 0
    M.detour_until = -1
    M.detour_a = 0.0
    M.heard = {}
    M.role_note = None
    M.deaths_me = 0
    M.last_enemy = None
    M.bump_tick = -999
    M.bump_n = (0.0, 1.0)
    M.bump_side = None
    M.bump_pos = (0.0, 0.0)
    M.watch = None
    seed = int(S.get("seed", 0)) * 1000003 + int(me.get("id", 0)) * 7919 + M.match_no * 104729
    M.rng = random.Random(seed)
    M.p = dict(S)
    M.team_seed = None
    if S.get("chaos"):
        if SEED is not None:
            base = int(SEED) * 1000003 + M.match_no
        else:
            base = random.SystemRandom().randrange(1 << 30)
        _set_team_seed(base + sum(map(ord, str(me.get("team", "")))))


def _set_team_seed(ts):
    """Chaos: one team-wide draw. Player 1 broadcasts its seed at spawn; mates adopt it."""
    M.team_seed = ts
    M.p = dict(S)
    _chaos_params(random.Random(ts), M.p)


def _chaos_params(rng, p):
    p["vsafe"] = rng.uniform(9.6, 10.85)
    p["vfast"] = rng.choice((11.5, 14.0, 16.0, _VTOP, _VTOP, _VTOP))
    p["roles"] = rng.choice((
        ("cycle", "cycle", "guard"),
        ("cycle", "cycle", "flex"),
        ("cycle", "cycle", "cycle"),
        ("attack", "attack", "attack"),
        ("attack", "guard", "intercept"),
        ("cycle", "camp", "attack"),
        ("cycle", "escort", "guard"),
        ("attack", "camp", "harass"),
        ("guard", "sentry", "cycle"),
    ))
    p["support"] = rng.choice(("escort", "wait", "harass"))
    p["lanes"] = tuple(rng.choice((0.0, 0.0, 0.0, 15.0, -15.0, 30.0, -30.0)) for _ in range(3))
    p["aggr"] = rng.choice((1, 2, 2, 3))
    p["tie_margin"] = rng.choice((-0.3, 0.5, 1.5))
    p["jump"] = rng.uniform(0.3, 1.0)
    p["spawn_jump"] = rng.random() < 0.6
    p["noise"] = rng.uniform(0.0, 0.2)
    p["trust_trail"] = rng.random() < 0.5
    p["cycle_defend"] = rng.random() < 0.5
    p["camp_grabber"] = rng.choice((0, 1, 2))
    p["guard_v"] = rng.uniform(7.0, 12.0)
    p["leash"] = rng.uniform(18.0, 30.0)
    if rng.random() < 0.5:
        p["watch"] = ((rng.uniform(5.0, 9.0), 3.0, 1.0), (rng.uniform(7.0, 10.0), 4.0, -1.0))


# ------------------------------------------------------------------ memory
def _cell(x, y):
    i = int(x + 100.0)
    j = int(y + 100.0)
    if i < 0:
        i = 0
    elif i >= _N:
        i = _N - 1
    if j < 0:
        j = 0
    elif j >= _N:
        j = _N - 1
    return j * _N + i


def _ok(x, y):
    """True if the point is known to be clear at ground level."""
    if x > 99.5 or x < -99.5 or y > 99.5 or y < -99.5:
        return True
    hx, hy = M.home
    if (x - hx) * (x - hx) + (y - hy) * (y - hy) < _HOME_R2:
        return True
    ex, ey = M.ehome
    if (x - ex) * (x - ex) + (y - ey) * (y - ey) < _HOME_R2:
        return True
    return M.safe[_cell(x, y)] != 0


def _mark_line(x0, y0, x1, y1):
    d = math.hypot(x1 - x0, y1 - y0)
    n = int(d * 2.0) + 1
    safe = M.safe
    top = _N - 1
    for k in range(n + 1):
        t = k / n
        i = int(x0 + (x1 - x0) * t + 100.0)  # _cell, inlined
        j = int(y0 + (y1 - y0) * t + 100.0)
        if i < 0:
            i = 0
        elif i > top:
            i = top
        if j < 0:
            j = 0
        elif j > top:
            j = top
        safe[j * _N + i] = 1


def _unmark(x, y, r):
    safe = M.safe
    ir = int(r) + 1
    for dj in range(-ir, ir + 1):
        for di in range(-ir, ir + 1):
            safe[_cell(x + di, y + dj)] = 0


def _add_circle(cx, cy, r, share=True):
    circles = M.circles
    for i in range(len(circles)):
        ox, oy, orr = circles[i]
        d = math.hypot(ox - cx, oy - cy)
        if d + r <= orr + 0.3:
            return
        if d < orr + r - 1.0:
            # overlapping estimates of one obstacle: grow into an enclosing circle
            nr = min(9.0, (d + orr + r) / 2.0)
            if d > 1e-6:
                k = (nr - orr) / d
                nx, ny = ox + (cx - ox) * k, oy + (cy - oy) * k
            else:
                nx, ny = ox, oy
            circles[i] = (nx, ny, max(nr, orr))
            _unmark(cx, cy, r - 0.5)
            if share:
                _share(("c", round(cx, 1), round(cy, 1), round(r, 1)))
            return
    circles.append((cx, cy, r))
    if len(M.circles) > 80:
        del M.circles[0]
    _unmark(cx, cy, r - 0.5)
    if share:
        _share(("c", round(cx, 1), round(cy, 1), round(r, 1)))


def _share(item):
    M.seen.add(item)
    M.share.append(item)
    if len(M.share) > 48:
        del M.share[0]


def _close_seg():
    if M.seg0 is not None and M.seglast is not None:
        x0, y0 = M.seg0
        x1, y1 = M.seglast
        if (x1 - x0) ** 2 + (y1 - y0) ** 2 > 16.0:
            _share(("s", round(x0, 1), round(y0, 1), round(x1, 1), round(y1, 1)))
    M.seg0 = None
    M.segdir = None
    M.seglast = None


def _track_seg(x, y, ground):
    if not ground:
        _close_seg()
        return
    if M.seg0 is None:
        M.seg0 = (x, y)
        M.seglast = (x, y)
        return
    x0, y0 = M.seg0
    dx, dy = x - x0, y - y0
    if M.segdir is None:
        d = math.hypot(dx, dy)
        if d > 0.8:
            M.segdir = (dx / d, dy / d)
        M.seglast = (x, y)
        return
    ux, uy = M.segdir
    if abs(dx * uy - dy * ux) > 0.3 or dx * ux + dy * uy < 0.0:
        last = M.seglast
        _close_seg()
        M.seg0 = last
        M.seglast = (x, y)
        return
    M.seglast = (x, y)


def _perceive(obs, me, tick):
    x, y, z = me["x"], me["y"], me["z"]
    ground = z < 1.0 + 1e-6
    prev = M.prev
    bumped = False
    if prev is not None and prev[0] == tick - 1:
        _, px, py, pvx, pvy, pu, pground = prev
        yaw = me["yaw"]
        evx = pvx + math.sin(yaw) * pu * 6.0
        evy = pvy + math.cos(yaw) * pu * 6.0
        es = math.hypot(evx, evy)
        if es > 18.0:
            evx *= 18.0 / es
            evy *= 18.0 / es
            es = 18.0
        es *= 0.98
        if es > 0.6 and me["speed"] < 0.02 and abs(x) < 98.5 and abs(y) < 98.5:
            bumped = True
            ux, uy = evx / es, evy / es
            # push-out direction = obstacle normal at the contact
            nx = x - (px + evx * _DT)
            ny = y - (py + evy * _DT)
            nn = math.hypot(nx, ny)
            if nn < 1e-4:
                nx, ny = -ux, -uy
            else:
                nx, ny = nx / nn, ny / nn
            cx, cy = x - nx, y - ny
            _add_circle(cx - nx * 2.6, cy - ny * 2.6, 3.2, S.get("share", False))
            if tick - M.bump_tick >= 60:
                M.bump_side = None
            M.bump_n = (nx, ny)
            M.bump_pos = (x, y)
            M.bump_tick = tick
        elif ground and pground:
            _mark_line(px, py, x, y)
    if bumped:
        _close_seg()
    else:
        _track_seg(x, y, ground)

    for m in obs.get("death_messages") or ():
        key = (m.get("player"), m.get("tick"))
        if key in M.deaths:
            continue
        M.deaths.add(key)
        if m.get("reason") == "wall" and m.get("x") is not None:
            _add_circle(m["x"], m["y"], 2.2, False)
        if m.get("player") == me.get("player"):
            M.deaths_me += 1

    if S.get("share"):
        trust = S.get("trust_sonar", True)
        for msg in obs.get("sonar_receive") or ():
            v = msg.get("value") if isinstance(msg, dict) else None
            if not isinstance(v, tuple) or len(v) != 4 or v[0] != S["tag"]:
                continue
            M.heard[v[1]] = (tick, v[2], msg.get("from_id"))
            item = v[3]
            if not isinstance(item, tuple) or item in M.seen:
                continue
            M.seen.add(item)
            if item[0] == "s" and len(item) == 5 and trust:
                _mark_line(item[1], item[2], item[3], item[4])
            elif item[0] == "c" and len(item) == 4:
                _add_circle(item[1], item[2], item[3], False)

    for e in obs.get("visible_enemies") or ():
        eid = e.get("id")
        eg = e.get("z", 1.0) < 1.0 + 1e-6
        last = M.enemy_last.get(eid)
        if last is not None and last[0] == tick - 1 and last[3] and eg:
            _mark_line(last[1], last[2], e["x"], e["y"])
        M.enemy_last[eid] = (tick, e["x"], e["y"], eg)
        M.last_enemy = (tick, e["x"], e["y"])
    return bumped


# --------------------------------------------------------------- movement
def _avoid(x, y, a, dist, tick):
    circles = M.circles
    if not circles:
        return a
    ux, uy = math.sin(a), math.cos(a)
    look = dist if dist < 30.0 else 30.0
    best = None
    bd = 1e9
    for idx, (cx, cy, r) in enumerate(circles):
        rx, ry = cx - x, cy - y
        along = rx * ux + ry * uy
        R = r + 1.7
        if along < -R or along > look + R:
            continue
        perp = rx * uy - ry * ux
        if perp >= R or perp <= -R:
            continue
        dc = math.hypot(rx, ry)
        if dc < bd:
            bd = dc
            best = (idx, cx, cy, R, perp, dc)
    if best is None:
        return a
    idx, cx, cy, R, perp, dc = best
    side = None
    if M.bump_side is not None and tick - M.bump_tick < 60:
        bx, by = M.bump_pos
        if (bx - cx) ** 2 + (by - cy) ** 2 < (R + 2.0) ** 2:
            side = M.bump_side
    if side is None:
        side = M.side.get(idx)
    if side is None:
        side = -1.0 if perp > 0 else 1.0
    M.side[idx] = side
    ca = math.atan2(cx - x, cy - y)
    off = _PI / 2.0 + 0.5 if dc <= R else math.asin(R / dc) + 0.1
    return _norm(ca + side * off)


def _gov_dir(x, y, ux, uy, sp):
    L = 2.5 + sp * 0.16
    hx, hy = M.home
    ex, ey = M.ehome
    safe = M.safe
    d = 0.7
    while d <= L:
        px = x + ux * d  # _ok(px, py), inlined
        py = y + uy * d
        if not (px > 99.5 or px < -99.5 or py > 99.5 or py < -99.5
                or (px - hx) * (px - hx) + (py - hy) * (py - hy) < _HOME_R2
                or (px - ex) * (px - ex) + (py - ey) * (py - ey) < _HOME_R2
                or safe[_cell(px, py)] != 0):
            return False
        d += 0.7
    return True


def _near_circle(x, y, pad):
    for cx, cy, r in M.circles:
        rr = r + pad
        if (cx - x) ** 2 + (cy - y) ** 2 < rr * rr:
            return True
    return False



def _vcap(me, h):
    x, y = me["x"], me["y"]
    sp = me["speed"]
    p = M.p
    fast = p["vfast"]
    if fast <= p["vsafe"]:
        return p["vsafe"]
    if not _gov_dir(x, y, math.sin(h), math.cos(h), max(sp, 12.0)):
        return p["vsafe"]
    if sp > 1.5:
        if not _gov_dir(x, y, me["vx"] / sp, me["vy"] / sp, sp):
            return p["vsafe"]
    if _near_circle(x, y, 2.5):
        return p["vsafe"]
    return fast


def _throttle(me, vt, sign):
    yaw = me["yaw"]
    fx, fy = math.sin(yaw), math.cos(yaw)
    vx, vy = me["vx"], me["vy"]
    a = vx * fx + vy * fy
    b2 = vx * vx + vy * vy - a * a
    want = vt / 0.98
    if want > 18.0:
        want = 18.0
    w2 = want * want
    tl = 0.0 if w2 <= b2 else sign * math.sqrt(w2 - b2)
    return _clamp((tl - a) / 6.0)


def _drive(me, tick, tx, ty, v, rev=True, arrive=0.0, vmin=0.0):
    x, y, yaw, sp = me["x"], me["y"], me["yaw"], me["speed"]
    dx, dy = tx - x, ty - y
    dist = math.hypot(dx, dy)
    if dist < 1e-6:
        M.goal = (yaw, 0.0)
        return _throttle(me, 0.0, 1.0), 0.0
    a = math.atan2(dx, dy)
    if tick - M.bump_tick < 10:
        nx, ny = M.bump_n
        if M.bump_side is None:
            dt_ = (-ny) * dx + nx * dy
            M.bump_side = (1.0 if dt_ > 0 else -1.0) if abs(dt_) > 0.1 * dist else M.rng.choice((-1.0, 1.0))
        sd = M.bump_side
        a = math.atan2(-ny * sd + 0.3 * nx, nx * sd + 0.3 * ny)
        v = min(v, 7.0)
        arrive = 0.0
    elif tick < M.detour_until:
        a = M.detour_a
    else:
        a = _avoid(x, y, a, dist, tick)
    noise = M.p.get("noise", 0.0)
    if noise:
        a += noise * math.sin(tick * 0.07 + M.match_no)
    vx, vy = me["vx"], me["vy"]
    vt = v
    if sp > 1.0 and dist < 40.0:
        ae = abs(_norm(a - math.atan2(vx, vy)))
        if ae > 0.08:
            R = 0.8 * dist / (2.0 * math.sin(min(ae, 1.5)))
            vt = min(vt, max(2.0, 3.2 * R / (1.0 + 0.151 * R)))
    if arrive > 0.0:
        vt = min(vt, max(0.0, (dist - arrive) * 3.0))
    if vt < vmin:
        vt = min(vmin, v)
    vt = min(vt, _vcap(me, a))
    M.goal = (a, vt)
    # velocity-vector control: thrust (forward or reverse) along the velocity error
    sa, ca = math.sin(a), math.cos(a)
    k = vt / 0.98
    dvx = k * sa - vx
    dvy = k * ca - vy
    dm = math.hypot(dvx, dvy)
    if dm > 1.5:
        da = math.atan2(dvx, dvy)
    else:
        da = a
    ef = _norm(da - yaw)
    er = _norm(da - yaw - _PI)
    hyst = 0.4 if rev else 1.2
    if M.rev:
        if abs(ef) + hyst < abs(er):
            M.rev = False
    elif abs(er) + hyst < abs(ef):
        M.rev = True
    if dm <= 1.5 and not rev and M.rev:
        M.rev = False
    err = er if M.rev else ef
    if dm <= 1.5 and M.rev:
        err = _norm(a - yaw - _PI)
    rate = 3.2 * (1.0 - 0.85 * min(1.0, sp / 18.0)) * _DT
    turn = _clamp(err / rate)
    ny = yaw + turn * rate
    fx, fy = math.sin(ny), math.cos(ny)
    u = _clamp((dvx * fx + dvy * fy) / 6.0)
    if abs(_norm(da - ny - (_PI if M.rev else 0.0))) > 0.7 and u * (vx * fx + vy * fy) >= 0.0:
        u = 0.0  # misaligned thrust would only bend the velocity into an orbit
    # never let the resulting speed exceed the target (perpendicular thrust adds speed)
    lim = max(vt, 0.5) / 0.98
    a1 = vx * fx + vy * fy
    nvx, nvy = vx + 6.0 * u * fx, vy + 6.0 * u * fy
    if nvx * nvx + nvy * nvy > lim * lim:
        c0 = vx * vx + vy * vy - lim * lim
        disc = a1 * a1 - c0
        if disc >= 0.0:
            r = math.sqrt(disc)
            lo, hi = (-a1 - r) / 6.0, (-a1 + r) / 6.0
            u = _clamp(min(max(u, lo), hi))
        else:
            u = _clamp(-a1 / 6.0)
    # stuck handling: pushing without moving
    if vt > 3.0 and sp < 0.8:
        M.stuck += 1
        if M.stuck > 12:
            M.stuck = 0
            M.detour_until = tick + 14
            M.detour_a = _norm(a + M.rng.choice((-1.0, 1.0)) * (1.2 + M.rng.random()))
    else:
        M.stuck = 0
    return u, turn


# ----------------------------------------------------------------- combat
def _contact_time(me, e, rad=2.15):
    rx, ry = e["x"] - me["x"], e["y"] - me["y"]
    wx, wy = e["vx"] - me["vx"], e["vy"] - me["vy"]
    c = rx * rx + ry * ry - rad * rad
    if c <= 0.0:
        return 0.0
    b = 2.0 * (rx * wx + ry * wy)
    a = wx * wx + wy * wy
    if b >= 0.0 or a < 1e-6:
        return None
    disc = b * b - 4.0 * a * c
    if disc < 0.0:
        return None
    return (-b - math.sqrt(disc)) / (2.0 * a)


def _danger(me, enemies, horizon=0.5):
    """Most urgent enemy that could ram us while at least as fast."""
    best = None
    bt = horizon
    msp = me["speed"]
    for e in enemies:
        if abs(e["z"] - me["z"]) > 1.6:
            continue
        d = math.hypot(e["x"] - me["x"], e["y"] - me["y"])
        es = e["speed"]
        t = _contact_time(me, e)
        if t is None:
            if d < 4.0 and es + 2.0 > msp:
                t = 0.15
            else:
                continue
        if t < bt and es + 1.0 > msp:
            bt = t
            best = e
    return best, bt


def _ram_target(me, enemies, radius, margin, own_carrier_id, leash=None):
    best = None
    bscore = 1e9
    x, y = me["x"], me["y"]
    for e in enemies:
        if e["z"] > 1.9:
            continue
        if leash is not None and e["id"] != own_carrier_id:
            lx, ly, lr = leash
            if (e["x"] - lx) ** 2 + (e["y"] - ly) ** 2 > lr * lr:
                continue
        dx, dy = e["x"] - x, e["y"] - y
        d = math.hypot(dx, dy)
        if d > radius or d < 1e-6:
            continue
        a = math.atan2(dx, dy)
        reach = M.p["vsafe"]
        if M.p["vfast"] > reach and _gov_dir(x, y, math.sin(a), math.cos(a), _VTOP):
            reach = M.p["vfast"]
        m = min(margin, -0.3) if e["id"] == own_carrier_id else margin
        if reach < e["speed"] + m:
            continue
        score = d - (25.0 if e["id"] == own_carrier_id else 0.0)
        if score < bscore:
            bscore = score
            best = (e, reach)
    return best


def _lead(me, ex, ey, evx, evy, v):
    d = math.hypot(ex - me["x"], ey - me["y"])
    t = min(1.5, d / max(v, 6.0))
    return ex + evx * t, ey + evy * t


# ------------------------------------------------------------------ roles
def _ctx(obs, me):
    own = obs["own_flag"]
    others = obs.get("other_flags") or []
    of = others[0] if others else None
    hx, hy = M.home
    ex, ey = M.ehome
    L = math.hypot(ex - hx, ey - hy) or 1.0
    ux, uy = (ex - hx) / L, (ey - hy) / L
    base = me["id"] - (me["player"] - 1)
    mates = (base, base + 1, base + 2)
    efc = of["carried_by"] if of is not None else -1
    c = _Mem()
    c.own = own
    c.of = of
    c.hx, c.hy, c.ex, c.ey = hx, hy, ex, ey
    c.L, c.ux, c.uy = L, ux, uy
    c.px, c.py = uy, -ux
    c.i_carry = me.get("carrying") is not None
    c.mate_carry = efc != -1 and efc in mates and efc != me["id"]
    c.flag_free = of is not None and efc == -1
    c.fx = of["x"] if of is not None else ex
    c.fy = of["y"] if of is not None else ey
    c.stolen = own.get("carried_by", -1) != -1
    c.own_carrier = own.get("carried_by", -1)
    c.s = (me["x"] - hx) * ux + (me["y"] - hy) * uy
    return c


def _intent(tx, ty, v, rev=True, arrive=0.0, aggr=0, dodge=True, code="-"):
    return [tx, ty, v, rev, arrive, aggr, dodge, code]


def _lane_point(c, lane, toward_enemy):
    if not lane:
        return None
    mx = c.hx + c.ux * c.L * 0.5 + c.px * lane
    my = c.hy + c.uy * c.L * 0.5 + c.py * lane
    return mx, my


def _go_flag(me, c, lane, aggr):
    if lane and c.s < c.L * 0.42:
        mx, my = _lane_point(c, lane, True)
        return _intent(mx, my, _VTOP, True, 0.0, aggr, True, "A")
    return _intent(c.fx, c.fy, _VTOP, True, 0.0, aggr, True, "A")


def _carry(me, c, lane):
    if lane and c.s > c.L * 0.58:
        mx, my = _lane_point(c, lane, False)
        return _intent(mx, my, _VTOP, True, 0.0, 0, True, "C")
    return _intent(c.hx, c.hy, _VTOP, True, 0.0, 0, True, "C")


def _pingpong(me, ax, ay, bx, by, v, aggr, code, tol=1.5):
    """Shuttle between A and B on one axis (no turning: forward/reverse)."""
    tx, ty = (ax, ay) if M.pp > 0 else (bx, by)
    dx, dy = bx - ax, by - ay
    L = math.hypot(dx, dy) or 1.0
    s = ((me["x"] - ax) * dx + (me["y"] - ay) * dy) / L
    if M.pp > 0 and s < tol:
        M.pp = -1
        tx, ty = bx, by
    elif M.pp < 0 and s > L - tol:
        M.pp = 1
        tx, ty = ax, ay
    if s < -4.0 or s > L + 4.0 or abs((me["x"] - ax) * dy - (me["y"] - ay) * dx) / L > 4.0:
        sc = min(L, max(0.0, s + (-6.0 if M.pp > 0 else 6.0)))
        tx, ty = ax + dx / L * sc, ay + dy / L * sc
    return _intent(tx, ty, v, True, 0.0, aggr, True, code)


def _wait(me, c, aggr):
    """Hover over the enemy flag home so a reset flag is re-taken at once."""
    if c.flag_free:
        return _intent(c.fx, c.fy, _VTOP, True, 0.0, aggr, True, "A")
    ex, ey = c.ex, c.ey
    return _pingpong(me, ex - c.ux * 3.0, ey - c.uy * 3.0,
                     ex + c.ux * 9.0, ey + c.uy * 9.0, M.p.get("wait_v", 12.0), aggr, "W")


def _chase_ok(me, c):
    """False when the carrier is far, running away and at least as fast as we can go."""
    tr = M.trail
    if len(tr) < 3:
        return True
    rx, ry = c.own["x"] - me["x"], c.own["y"] - me["y"]
    d = math.hypot(rx, ry)
    if d < 25.0:
        return True
    evx = (tr[-1][0] - tr[-3][0]) / (2 * _DT)
    evy = (tr[-1][1] - tr[-3][1]) / (2 * _DT)
    away = (evx * rx + evy * ry) / d
    reach = M.p["vfast"] if M.p.get("trust_trail") else M.p["vsafe"]
    return away < reach - 2.0


def _orbit(me, cx, cy, R, v, aggr, code, lead=0.7):
    th = math.atan2(me["x"] - cx, me["y"] - cy) + lead * M.p.get("orbit_dir", 1.0)
    return _intent(cx + R * math.sin(th), cy + R * math.cos(th), v, False, 0.0, aggr, True, code)


def _sweep(me, c, ang, w, v, aggr, off=0.0):
    """High-speed shuttle through (or near) our flag along a line at angle `ang` to the axis."""
    ca, sa = math.cos(ang), math.sin(ang)
    dx, dy = c.ux * ca + c.px * sa, c.uy * ca + c.py * sa
    bx, by = c.hx + c.ux * off, c.hy + c.uy * off
    return _pingpong(me, bx + dx * w, by + dy * w, bx - dx * w, by - dy * w, v, aggr, "G", 2.5)


def _watch_drive(me, cx, cy, R, v, sense):
    """Orbit (cx, cy) at radius R and speed v while facing inward, so the vision cone
    keeps sweeping the flag area (thrust is mostly centripetal)."""
    x, y, yaw = me["x"], me["y"], me["yaw"]
    vx, vy = me["vx"], me["vy"]
    rx, ry = x - cx, y - cy
    r = math.hypot(rx, ry) or 1e-6
    nx, ny = rx / r, ry / r                       # outward normal
    tx, ty = -ny * sense, nx * sense               # tangent
    vr = vx * nx + vy * ny
    vtan = vx * tx + vy * ty
    a_in = vtan * vtan / max(r, 2.0) * _DT + _clamp(0.3 * (r - R), -1.5, 1.5) + 0.5 * vr
    a_tan = _clamp((v - vtan) * 0.3, -2.0, 2.0) + vtan * 0.0205
    dvx = -nx * a_in + tx * a_tan
    dvy = -ny * a_in + ty * a_tan
    inward = math.atan2(-nx, -ny)
    beta = _clamp(math.atan2(a_tan, max(0.3, a_in)), -1.2, 1.2)
    da = inward + sense * beta
    err = _norm(da - yaw)
    sp = me["speed"]
    rate = 3.2 * (1.0 - 0.85 * min(1.0, sp / 18.0)) * _DT
    turn = _clamp(err / rate)
    nyaw = yaw + turn * rate
    fx, fy = math.sin(nyaw), math.cos(nyaw)
    u = _clamp((dvx * fx + dvy * fy) / 6.0)
    lim = (v + 1.5) / 0.98
    a1 = vx * fx + vy * fy
    nvx, nvy = vx + 6.0 * u * fx, vy + 6.0 * u * fy
    if nvx * nvx + nvy * nvy > lim * lim:
        c0 = vx * vx + vy * vy - lim * lim
        disc = a1 * a1 - c0
        if disc >= 0.0:
            rr = math.sqrt(disc)
            u = _clamp(min(max(u, (-a1 - rr) / 6.0), (-a1 + rr) / 6.0))
        else:
            u = _clamp(-a1 / 6.0)
    return u, turn


def _guard(me, c, aggr):
    if c.stolen and _chase_ok(me, c):
        cr = M.p.get("chase_r")
        if cr is None or me["player"] != 1 or \
                math.hypot(c.own["x"] - c.hx, c.own["y"] - c.hy) < cr:
            return _intercept(me, c, aggr)
    v = M.p.get("guard_v", 9.0)
    wr = M.p.get("watch")
    if wr:
        k = 0 if me["player"] == 1 else 1
        R, off, sense = wr[k]
        cx, cy = c.hx + c.ux * off, c.hy + c.uy * off
        if abs(math.hypot(me["x"] - cx, me["y"] - cy) - R) < 4.0:
            M.watch = (cx, cy, R, v, sense)
        return _intent(cx + c.ux * R, cy + c.uy * R, v, True, 0.0, aggr, True, "G")
    sw = M.p.get("sweep")
    if sw:
        k = 0 if me["player"] == 1 else 1
        return _sweep(me, c, sw[k], M.p.get("sweep_w", 12.0), v, aggr, M.p.get("sweep_off", 0.0))
    if M.p.get("guard_orbit"):
        R = M.p["guard_orbit"]
        off = M.p.get("orbit_off", R * 0.5)
        return _orbit(me, c.hx + c.ux * off, c.hy + c.uy * off, R, v, aggr, "G")
    return _pingpong(me, c.hx + c.ux * 13.0, c.hy + c.uy * 13.0,
                     c.hx + c.ux * 1.0, c.hy + c.uy * 1.0, v, aggr, "G")


def _sentry(me, c, aggr):
    if c.stolen and _chase_ok(me, c):
        return _intercept(me, c, aggr)
    if M.p.get("sweep"):
        return _guard(me, c, aggr)
    v = M.p.get("sentry_v", M.p.get("guard_v", 9.0))
    d, w = M.p.get("sentry_d", 12.0), M.p.get("sentry_w", 10.0)
    bx, by = c.hx + c.ux * d, c.hy + c.uy * d
    return _pingpong(me, bx + c.px * w, by + c.py * w,
                     bx - c.px * w, by - c.py * w, v, aggr, "G")


def _intercept(me, c, aggr):
    ox, oy = c.own["x"], c.own["y"]
    tr = M.trail
    evx = evy = 0.0
    if len(tr) >= 3:
        evx = (tr[-1][0] - tr[-3][0]) / (2 * _DT)
        evy = (tr[-1][1] - tr[-3][1]) / (2 * _DT)
    tx, ty = _lead(me, ox, oy, evx, evy, 12.0)
    x, y = me["x"], me["y"]
    d = math.hypot(ox - x, oy - y)
    if M.p.get("trust_trail") and d > 12.0 and len(tr) > 8:
        # follow the carrier's own (survived) path when we are on it
        bi, bd = -1, 9.0
        for i in range(max(0, len(tr) - 400), len(tr), 3):
            q = tr[i]
            dd = (q[0] - x) ** 2 + (q[1] - y) ** 2
            if dd < bd:
                bd, bi = dd, i
        if bi >= 0:
            j = min(len(tr) - 1, bi + 8)
            tx, ty = tr[j]
    return _intent(tx, ty, _VTOP, False, 0.0, max(aggr, 2), False, "I")


def _camp(me, c, aggr, side):
    ex, ey = c.ex, c.ey
    if c.stolen:
        ox, oy = c.own["x"], c.own["y"]
        if math.hypot(ox - ex, oy - ey) < 45.0:
            return _intercept(me, c, 3)
    ax = ex + c.ux * 4.0 + c.px * side
    ay = ey + c.uy * 4.0 + c.py * side
    bx = ex + c.ux * 15.0 + c.px * side
    by = ey + c.uy * 15.0 + c.py * side
    return _pingpong(me, ax, ay, bx, by, M.p.get("camp_v", 13.0), aggr, "K")


def _harass(me, c, aggr):
    if c.stolen and _chase_ok(me, c):
        return _intercept(me, c, 3)
    le = M.last_enemy
    tick = M.last_tick
    if le is not None and tick - le[0] < 80:
        return _intent(le[1], le[2], _VTOP, False, 0.0, 3, True, "H")
    mx = c.hx + c.ux * c.L * 0.5 + c.px * 25.0 * math.sin(tick * 0.004)
    my = c.hy + c.uy * c.L * 0.5 + c.py * 25.0 * math.sin(tick * 0.004)
    return _intent(mx, my, 12.0, False, 2.0, max(aggr, 2), True, "H")


def _escort(me, c, aggr):
    if not c.mate_carry:
        return None
    return _intent(c.fx - c.ux * 0.0, c.fy, _VTOP, True, 5.0, max(aggr, 2), True, "E")


def _role_intent(me, c, role, player, tick):
    p = M.p
    lane = p.get("lanes", (0.0, 0.0, 0.0))[player - 1]
    aggr = p.get("aggr", 2)
    if c.i_carry:
        return _carry(me, c, lane)
    if role == "attack":
        if c.mate_carry:
            how = p.get("support", "escort")
            if how == "wait":
                return _wait(me, c, aggr)
            if how == "escort":
                return _escort(me, c, aggr)
            return _harass(me, c, aggr)
        return _go_flag(me, c, lane, aggr)
    if role == "cycle":
        if c.stolen and p.get("cycle_defend"):
            ox, oy = c.own["x"], c.own["y"]
            if math.hypot(ox - me["x"], oy - me["y"]) < p.get("defend_r", 25.0):
                return _intercept(me, c, 3)
        if c.mate_carry:
            if p.get("share") and _waiter_taken(me, tick):
                return _escort(me, c, aggr)
            return _wait(me, c, aggr)
        return _go_flag(me, c, lane, aggr)
    if role == "flex":
        if c.stolen and _chase_ok(me, c):
            ox, oy = c.own["x"], c.own["y"]
            if math.hypot(ox - me["x"], oy - me["y"]) < p.get("flex_r", 50.0):
                return _intercept(me, c, 3)
        role = "cycle"
    if role == "guard":
        return _guard(me, c, max(aggr, 3))
    if role == "sentry":
        return _sentry(me, c, max(aggr, 3))
    if role == "intercept":
        if c.stolen and _chase_ok(me, c):
            return _intercept(me, c, 3)
        return _sentry(me, c, 3)
    if role == "camp":
        if player == p.get("camp_grabber", 0) and c.flag_free:
            ok = True
            for e in M.vis:
                if math.hypot(e["x"] - c.fx, e["y"] - c.fy) < 10.0:
                    ok = False
            if ok and math.hypot(me["x"] - c.fx, me["y"] - c.fy) < 22.0:
                return _intent(c.fx, c.fy, _VTOP, True, 0.0, aggr, True, "A")
        side = 6.0 if player % 2 else -6.0
        return _camp(me, c, max(aggr, 3), side)
    if role == "harass":
        return _harass(me, c, aggr)
    if role == "escort":
        r = _escort(me, c, aggr)
        if r is not None:
            return r
        if c.stolen:
            return _intercept(me, c, 3)
        return _go_flag(me, c, lane, aggr)
    return _go_flag(me, c, lane, aggr)


def _waiter_taken(me, tick):
    for pl, (t, code, _fid) in M.heard.items():
        if tick - t < 6 and code == "W" and pl < me["player"]:
            return True
    return False


# ------------------------------------------------------------------- main
def decide(observation):
    obs = observation
    me = obs["self"]
    tick = obs["tick"]
    if not M.ready or tick < M.last_tick:
        _reset(obs)
        M.spawn_tick = tick
    elif tick - M.last_tick > 1:
        M.spawn_tick = tick
    M.last_tick = tick
    own = obs.get("own_flag") or {}
    if own.get("at_home"):
        M.home = (own["x"], own["y"])
    if M.home is None:
        M.home = (90.0 if me["x"] > 0 else -90.0, 0.0)
    others = obs.get("other_flags") or []
    if others and others[0].get("at_home"):
        M.ehome = (others[0]["x"], others[0]["y"])
    if M.ehome is None:
        M.ehome = (-M.home[0], -M.home[1])

    if S.get("chaos") and tick < 4 and me.get("player") != 1:
        for msg in obs.get("sonar_receive") or ():
            v = msg.get("value") if isinstance(msg, dict) else None
            if isinstance(v, tuple) and len(v) == 4 and v[0] == S["tag"] and v[1] == 1 \
                    and v[2] == "S" and isinstance(v[3], int) and v[3] != M.team_seed:
                _set_team_seed(v[3])
    enemies = obs.get("visible_enemies") or []
    M.vis = enemies
    _perceive(obs, me, tick)

    c = _ctx(obs, me)
    if c.stolen:
        q = (c.own["x"], c.own["y"])
        tr = M.trail
        if not tr or tr[-1] != q:
            if tr and M.p.get("trust_trail") and (tr[-1][0] - q[0]) ** 2 + (tr[-1][1] - q[1]) ** 2 < 2.0:
                _mark_line(tr[-1][0], tr[-1][1], q[0], q[1])
            tr.append(q)
            if len(tr) > 1200:
                del tr[:200]
    elif M.trail:
        M.trail = []

    player = me.get("player", 1)
    roles = M.p["roles"]
    role = roles[(player - 1) % len(roles)]
    M.watch = None
    it = _role_intent(me, c, role, player, tick)
    tx, ty, v, rev, arrive, aggr, dodge, code = it

    jump = False
    hit = None
    vmin = 0.0
    if M.p.get("spawn_jump") and tick - M.spawn_tick < 2:
        jump = True
    if aggr > 0 and not c.i_carry and enemies:
        radius = (8.0, 14.0, 24.0, 36.0)[min(3, aggr)]
        margin = 2.5 if aggr < 3 else 1.5
        leash = None
        if code in ("G", "I", "K"):
            margin = M.p.get("tie_margin", -0.3)
        if code == "G":
            leash = (c.hx, c.hy, M.p.get("leash", 30.0))
        elif code == "K":
            leash = (c.ex, c.ey, M.p.get("leash", 30.0))
        hit = _ram_target(me, enemies, radius, margin, c.own_carrier, leash)
        if hit is not None:
            e, reach = hit
            tx, ty = _lead(me, e["x"], e["y"], e["vx"], e["vy"], reach)
            v, rev, arrive = _VTOP, False, 0.0
            vmin = min(reach, e["speed"] + 2.0)
            code = "R"
            if me["grounded"] and me["speed"] < e["speed"] + 0.3:
                t = _contact_time(me, e)
                if t is not None and t < 0.2:
                    jump = True
    if hit is None and dodge and enemies and me["grounded"]:
        e, t = _danger(me, enemies)
        if e is not None and t < 0.35 and M.rng.random() < M.p.get("jump", 1.0):
            jump = True

    M.goal = None
    if M.watch is not None and hit is None and tick - M.bump_tick >= 10:
        throttle, turn = _watch_drive(me, *M.watch)
    else:
        throttle, turn = _drive(me, tick, tx, ty, v, rev, arrive, vmin)
    M.prev = (tick, me["x"], me["y"], me["vx"], me["vy"], throttle, me["z"] < 1.0 + 1e-6)

    msg = None
    if S.get("share") or S.get("sonar"):
        item = None
        if M.share and S.get("share"):
            item = M.share[M.share_i % len(M.share)]
            M.share_i += 1
        msg = (S["tag"], player, code, item)
    elif S.get("chaos") and tick < 3 and player == 1:
        msg = (S["tag"], 1, "S", M.team_seed)
    return throttle, turn, jump, msg
